create or replace package body t009_checkout_api as
  function order_total(p_order_id in number) return number is
    l_items number;
    l_has_physical_items boolean;
  begin
    select nvl(sum(price * qty), 0)
      into l_items
      from t009_order_items
     where order_id = p_order_id;

    -- Check if the order contains any physical items (assuming weight_g > 0 indicates physical goods)
    select exinto l_has_physical_items
      from t009_order_items
     where order_id = p_order_id
     and weight_g > 0
     and ROWNUM = 1;

    if l_has_physical_items = 'Y' then
      return l_items + t009_shipping_pkg.shipping_cost(p_order_id);
    else
      return l_items; -- Only return item total if no physical items are present (digital goods)
    end if;
  end order_total;
end t009_checkout_api;
/

